def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'C'

    my_score = 0
    opp_score = 0
    for a, b in history:
        if a == 'C' and b == 'C':
            my_score += 3
            opp_score += 3
        elif a == 'C' and b == 'D':
            opp_score += 5
        elif a == 'D' and b == 'C':
            my_score += 5
        else:
            my_score += 1
            opp_score += 1

    opp_c = sum(1 for _, b in history if b == 'C')
    my_c = sum(1 for a, _ in history if a == 'C')
    opp_rate = opp_c / n

    def opp_coop_rate(start):
        cnt = 0
        tot = 0
        for i in range(start, n):
            tot += 1
            if history[i][1] == 'C':
                cnt += 1
        if tot == 0:
            return 0.5
        return cnt / tot

    recent_len = min(10, n)
    recent_opp = opp_coop_rate(n - recent_len)

    last_me, last_opp = history[-1]

    defection_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            defection_streak += 1
        else:
            break

    cooperation_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            cooperation_streak += 1
        else:
            break

    # Count our own recent defections
    my_recent_def = sum(1 for a, _ in history[-recent_len:] if a == 'D')

    score_diff = my_score - opp_score
    rounds_left = 100 - n

    # Opening: cooperate to invite mutual cooperation
    if n < 5:
        if n >= 1 and last_opp == 'D':
            # retaliate once, then return to cooperate
            if last_me == 'C':
                return 'D'
        return 'C'

    # Heavy exploitation: punish consistently
    if recent_opp <= 0.15 and defection_streak >= 2:
        return 'D'

    # Opponent mostly cooperative: maintain mutual cooperation, rare probe
    if opp_rate >= 0.85 and defection_streak == 0:
        if rounds_left > 25 and rng.random() < 0.04:
            return 'D'
        return 'C'

    # Opponent heavily defecting: defect
    if opp_rate < 0.3:
        if rounds_left > 10 and rng.random() < 0.08:
            return 'C'
        return 'D'

    # Endgame: exploit known cooperative opponent
    if rounds_left <= 2:
        if recent_opp >= 0.5:
            return 'D'
        return 'D'

    if rounds_left <= 5:
        if recent_opp >= 0.7:
            return 'C'
        if recent_opp <= 0.3:
            return 'D'
        if last_opp == 'C':
            return 'D'
        return 'D'

    # Repentance: if we defected and opponent still cooperated, return to cooperation
    if last_opp == 'C' and last_me == 'D':
        return 'C'

    # Opponent defected last round: respond
    if last_opp == 'D':
        # If opponent has been mostly cooperative, a single defection: punish then forgive
        if opp_rate >= 0.7:
            # if opponent defected only once recently, punish once
            recent_def = sum(1 for _, b in history[-recent_len:] if b == 'D')
            if recent_def <= 1:
                return 'D'
            # more than one recent defection but still high overall -> forgive
            return 'C'

        # If defection streak is long, keep defecting but occasionally forgive
        if defection_streak >= 3:
            if rng.random() < 0.1:
                return 'C'
            return 'D'

        # Moderate opponent: tit-for-tat with forgiveness
        if recent_opp >= 0.55:
            return 'C'
        if defection_streak >= 2:
            if rng.random() < 0.75:
                return 'D'
            return 'C'
        if rng.random() < 0.5:
            return 'D'
        return 'C'

    # Opponent cooperated last round
    # If we've been defecting a lot, return to cooperation
    if my_recent_def >= 3 and opp_rate >= 0.5:
        return 'C'

    # Steady cooperation
    if opp_rate >= 0.5:
        return 'C'

    # Low cooperation but opponent just cooperated: probe/defect occasionally
    if score_diff < -5:
        return 'D'
    if rng.random() < 0.3:
        return 'D'
    return 'C'
